import Vue from "vue";
import Vuex from "vuex";

Vue.use(Vuex);

export const store = new Vuex.Store({
  state: {
    _itemList: [],
    lat: null,
    lng: null,
    AvailableAmount: "",
    LoanRate: 0,
    _address: "",
    _zoomLevel: 13,
    rId: null,
    reback: false,
    l: null,
    r: null,
    t: null,
    b: null,
  },
  mutations: {
    init() {
      this.state._itemList = [];
      this.state.lat = null;
      this.state.lng = null;
      this.AvailableAmount = "";
      this.LoanRate = 0;
      this._address = "";
      this._zoomLevel = 13;
      this.rId = null;
      this.l = null;
      this.r = null;
      this.t = null;
      this.b = null;
    },
  },
});
